import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { ConnectionPool, type Connection } from "../src/labs/pool.ts";
import { AuditLog } from "../src/labs/audit.ts";
import { LabResultService, type LabResultInput } from "../src/labs/results.ts";
import { importFeed } from "../src/labs/feed.ts";

// In-memory database: every statement is a round trip; inserts inside BEGIN are only visible after COMMIT.
function database(failTable?: string) {
    const tables: Record<string, unknown[][]> = { lab_results: [], audit_log: [], critical_alerts: [] };
    const connect = (): Connection => {
        let tx: [string, unknown[]][] | null = null;
        return {
            async query(sql, params = []) {
                await tick();
                if (sql === "BEGIN") tx = [];
                else if (sql === "COMMIT") {
                    for (const [t, row] of tx ?? []) tables[t].push(row);
                    tx = null;
                } else if (sql === "ROLLBACK") tx = null;
                else {
                    const table = sql.replace("INSERT INTO ", "");
                    if (table === failTable) throw new Error(`${table}: connection reset`);
                    const seen = [...tables[table], ...(tx ?? []).filter(([t]) => t === table).map(([, r]) => r)];
                    if (table === "lab_results" && seen.some((r) => r[0] === params[0])) throw new Error(`duplicate accession ${params[0]}`);
                    if (tx) tx.push([table, params]);
                    else tables[table].push(params);
                }
            },
        };
    };
    return { tables, connect };
}

function lab(poolSize: number, failTable?: string) {
    const db = database(failTable);
    const pool = new ConnectionPool(db.connect, poolSize);
    const service = new LabResultService(pool, new AuditLog(pool), () => new Date("2026-11-19T08:30:00Z"));
    return { db, pool, service };
}

// Fail instead of hanging forever if everyone is waiting for a connection.
async function within<T>(ms: number, work: Promise<T>): Promise<T> {
    let timer: NodeJS.Timeout | undefined;
    const timeout = new Promise<never>((_, reject) => {
        timer = setTimeout(() => reject(new Error(`still waiting after ${ms}ms (deadlock?)`)), ms);
    });
    try {
        return await Promise.race([work, timeout]);
    } finally {
        clearTimeout(timer);
    }
}

const potassium = (accession: string, value: number): LabResultInput => ({
    accession, patientId: "p-1001", test: "potassium", value, refLow: 3.5, refHigh: 5.1,
});

test("a result is stored with its flag and an audit entry", async () => {
    const { db, service } = lab(4);
    assert.equal(await within(500, service.record(potassium("A1", 5.4), "dr.osei")), "high");
    assert.deepEqual(db.tables.lab_results, [["A1", "p-1001", "potassium", 5.4, "high"]]);
    assert.deepEqual(db.tables.audit_log, [["dr.osei", "lab_result.recorded", "A1", "2026-11-19T08:30:00.000Z"]]);
});

test("a critical value raises an alert for the care team", async () => {
    const { db, service } = lab(4);
    assert.equal(await within(500, service.record(potassium("A2", 6.9), "dr.osei")), "critical");
    assert.deepEqual(db.tables.critical_alerts, [["A2", "p-1001", "potassium"]]);
});

test("a duplicate accession is rolled back and its connection returned", async () => {
    const { db, pool, service } = lab(2);
    await within(500, service.record(potassium("A3", 4.2), "lab"));
    await assert.rejects(within(500, service.record(potassium("A3", 4.4), "lab")), /duplicate accession/);
    assert.equal(db.tables.lab_results.length, 1);
    assert.deepEqual(pool.stats(), { size: 2, inUse: 0, waiting: 0 });
});

test("invalid results are rejected before touching the database", async () => {
    const { db, pool, service } = lab(2);
    await assert.rejects(service.record({ ...potassium("A4", NaN) }, "lab"), /Invalid result/);
    await assert.rejects(service.record({ ...potassium("", 4) }, "lab"), /required/);
    assert.equal(db.tables.audit_log.length, 0);
    assert.equal(pool.stats().inUse, 0);
});

test("two results recorded at the same time on a two-connection pool both complete", async () => {
    const { db, service } = lab(2);
    await within(500, Promise.all([service.record(potassium("B1", 4.0), "lab"), service.record(potassium("B2", 4.1), "lab")]));
    assert.equal(db.tables.lab_results.length, 2);
    assert.equal(db.tables.audit_log.length, 2);
});

test("if the result is rolled back, its audit entry is rolled back too", async () => {
    const { db, service } = lab(3, "critical_alerts");
    await assert.rejects(within(500, service.record(potassium("C1", 7.5), "dr.osei")), /connection reset/);
    assert.deepEqual(db.tables.lab_results, []);
    assert.deepEqual(db.tables.audit_log, []);
});

test("an analyzer feed imported at pool-size concurrency finishes", async () => {
    const { db, pool, service } = lab(3);
    const batch = [4.0, 3.9, 6.8, 4.4, 3.1, 5.0, 4.7, 4.2].map((v, i) => potassium(`F${i}`, v));
    batch.push(potassium("F0", 4.0));
    const report = await within(1000, importFeed(service, batch, 3)).catch((err) => {
        console.log("pool when the feed stalled:", pool.stats());
        throw err;
    });
    assert.equal(report.recorded, 8);
    assert.deepEqual(report.critical, ["F2"]);
    assert.deepEqual(report.rejected.map((r) => r.accession), ["F0"]);
    assert.equal(db.tables.audit_log.length, 8);
    assert.deepEqual(pool.stats(), { size: 3, inUse: 0, waiting: 0 });
});
